+procedure SynLZcompress1passub(var ctx: TSynLzContext);
+var
+  src, dst, o: PAnsiChar;
+  v, cached, cwmask: cardinal;
+  h, t, tmax: PtrUInt;
+begin
+  cwmask := 1;
+  src := ctx.src;
+  dst := ctx.dst;
+  repeat
+    v := PCardinal(src)^;
+    h := ((v shr 12) xor v) and 4095;
+    o := ctx.offset[h];
+    ctx.offset[h] := src;
+    cached := v xor ctx.cache[h]; // o=nil if cache[h] is uninitialized
+    ctx.cache[h] := v;
+    if (cached and $00ffffff = 0) and
+       (o <> nil) and
+       (src - o > 2) then
+    begin
+      ctx.cwpoint^ := ctx.cwpoint^ or cwmask;
+      inc(src, 2);
+      inc(o, 2);
+      t := 1;
+      tmax := ctx.srcend - src - 1;
+      if tmax >= (255 + 16) then
+        tmax := (255 + 16);
+      while (o[t] = src[t]) and
+            (t < tmax) do
+        inc(t);
+      inc(src, t);
+      h := h shl 4;
+      // here we have always t>0
+      if t <= 15 then
+      begin
+        // mark 2 to 17 bytes -> size=1..15
+        PInteger(dst)^ := integer(t or h);
+        inc(dst, 2);
+      end
+      else
+      begin
+        // mark 18 to (255+16) bytes -> size=0, next byte=t
+        dec(t, 16);
+        PInteger(dst)^ := h; // size=0
+        dst[2] := ansichar(t);
+        inc(dst, 3);
+      end;
+    end
+    else
+    begin
+      dst^ := src^;
+      inc(src);
+      inc(dst);
+    end;
+    cwmask := cwmask shl 1;
+    if cwmask = 0 then
+    begin
+      ctx.cwpoint := pointer(dst);
+      PCardinal(dst)^ := 0;
+      inc(PCardinal(dst));
+      cwmask := 1;
+    end;
+  until src > ctx.srcendmatch;
+  ctx.src := src; // store end position
+  ctx.dst := dst;
+  ctx.cwmask := cwmask
+end;
